import type { AirobotSdkOptions } from './types';
import { createDom } from './helper';
import styles from './styles.module.less';

class AirobotSdk {
  private options: AirobotSdkOptions;
  private $root = document.body;
  private $container: HTMLElement | null = null;
  private $drawer: HTMLElement | null = null;

  constructor(options: AirobotSdkOptions) {
    this.options = options;
    this.init();
  }

  private createContainer = () => {
    const el = this.$container = createDom('div', this.$root);
    // 将抽屉设置为popover在最顶层
    el.setAttribute('popover', 'manual');
    el.classList.add(styles.airobot_container);
  }

  // 创建抽屉
  private createDrawer = () => {
    this.$drawer = createDom('div', this.$container!);
    this.$drawer.classList.add('')
    this.options;
  }

  // 初始化
  private init = () => {
    // 先创建容器
    this.createContainer();
    this.createDrawer();
  }

  public open = () => {
    if (this.$container) {
      this.$container.classList.add(styles.open);
      this.$container.showPopover();
    }
  }

  // 销毁
  public destroy = () => {

  }
}

export { AirobotSdk }

export default AirobotSdk